import{$ as e,X as t,a as n,et as r,ht as i,nt as a,tt as o,xt as s}from"./chunks/framework.B2_Ga-t4.js";var c=JSON.parse(`{"title":"私有 Storage 数据","description":"","frontmatter":{},"headers":[],"relativePath":"guide/storage.md","filePath":"guide/storage.md"}`),l={name:`guide/storage.md`},u={id:`私有-storage-数据`,tabindex:`-1`};function d(n,c,l,d,f,p){let m=s(`Badge`);return i(),e(`div`,null,[c[3]||=t(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /guide/storage.md for this page in Markdown format`,-1),t(`h1`,u,[c[0]||=o(`私有 Storage 数据 `,-1),a(m,{type:`pro`,text:`专业版`}),c[1]||=o(),c[2]||=t(`a`,{class:`header-anchor`,href:`#私有-storage-数据`,"aria-label":`Permalink to “私有 Storage 数据”`},`​`,-1)]),c[4]||=r(`<p>由于 localStorage 和 sessionStorage 的同源策略，同一域名下的 storage 数据会共享。如果你恰好需要在同一域名下部署两套(及以上)系统，不可避免会出现 storage 数据冲突，框架提供了一个 storage 类来解决这个问题。</p><p>解决同源 storage 数据冲突的方式就是增加前缀区分。</p><p>首先需要在环境变量中设置一个唯一且不重名的前缀：</p><div class="language-env"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># localStorage/sessionStorage 前缀</span></span>
<span class="line"><span># localStorage/sessionStorage prefix</span></span>
<span class="line"><span>VITE_APP_STORAGE_PREFIX = oc_</span></span></code></pre></div><p>然后就可以继续使用 <code>localStorage</code> 和 <code>sessionStorage</code> 了，框架重写了 <code>localStorage</code> 和 <code>sessionStorage</code> ，所以使用方式和原来一样，并且还增加了 2 个 API：</p><ul><li><code>localStorage.has(key)</code> / <code>sessionStorage.has(key)</code> 判断对象是否存在</li><li><code>localStorage.length</code> / <code>sessionStorage.length</code> 获取对象数量（只统计带前缀的 key）</li></ul>`,6)])}var f=n(l,[[`render`,d]]);export{c as __pageData,f as default};